function setView(next,{keepFilters=false,updateHash=true}={}){projectOpenGeneration++;if(view==='video'&&next!=='video')videoStudio?.cancel();view=next;library.hidden=['maker','video','collections','projects'].includes(view);workspaceRoot.hidden=!['collections','projects'].includes(view);maker.hidden=view!=='maker';videoMaker.hidden=view!=='video';if(!keepFilters){collectionId='';query='';topic='';reaction='';feed='best';page=1;sourceFilter='all';filter=next==='gifs'?'gif':'all';sort='featured';}document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(['collections','projects'].includes(next)){workspace.render(next);}else if(next==='maker'){if(!maker.innerHTML)initMaker();refreshTemplates();drawEditor();}else if(next==='video'){if(!videoStudio)videoStudio=createVideoMaker(videoMaker,{toast,downloadBlob,onSave:saveCloudCreation,onSaveProject:saveProject});}else render({updateHash});if(updateHash&&['maker','video','collections','projects'].includes(next))history.replaceState(null,'','#'+next);window.scrollTo({top:0,behavior:'instant'});}

function removalButton(m,detail=false){const removed=removedIds.has(m.id),busy=!syncReady||pendingRemovals.has(m.id)||pendingTags.has(m.id)||pendingCreationSaves.has(m.id);return `<button class="${detail?'button outline detail-removal':'remove-item'} ${removed?'restore-item':''}" data-remove="${escape(m.id)}" aria-label="${removed?'Restore':'Remove'} ${escape(m.title)}" ${busy?'disabled':''}>${pendingRemovals.has(m.id)?'Saving…':removed?'↶ Restore':'× Remove'}</button>`;}
async function setRemoved(id,removed){
 if(!syncReady||pendingRemovals.has(id)||pendingTags.has(id)||pendingCreationSaves.has(id))return;
 const m=findMedia(id);if(!m)return;
 pendingRemovals.add(id);render({updateHash:!selected});document.querySelectorAll('[data-remove]').forEach(b=>{if(b.dataset.remove===id)b.disabled=true;});
 try{await apiRequest('/api/removals',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,removed})});accountRevision++;if(removed)removedIds.add(id);else removedIds.delete(id);if(selected?.id===id)$('#detail').close();refreshTemplates();toast(removed?'Removed from your library.':'Restored to your library.',()=>setRemoved(id,!removed));}
 catch(error){toast(error.message||'Could not remove this item. Try again.');}
 finally{pendingRemovals.delete(id);render({updateHash:!selected});document.querySelectorAll('[data-remove]').forEach(b=>{if(b.dataset.remove===id)b.disabled=false;});}
}
function ratingButtons(m){return m.type==='template'||view==='removed'?'':`<div class="rating-buttons" aria-label="Rate ${escape(m.title)}"><button data-rate="${escape(m.id)}" data-rating="1" aria-pressed="${ratings[m.id]===1}" ${pendingRatings.has(m.id)?'disabled':''}>Hilarious</button><button data-rate="${escape(m.id)}" data-rating="-1" aria-pressed="${ratings[m.id]===-1}" ${pendingRatings.has(m.id)?'disabled':''}>Lame</button></div>`;}
async function setRating(id,value){if(!syncReady||pendingRatings.has(id))return;const previous=ratings[id]||0,next=previous===value?0:value;pendingRatings.add(id);try{await apiRequest('/api/ratings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,value:next})});accountRevision++;ratings[id]=next;toast(next===-1?'Marked lame. Hidden from Best Roasts.':next===1?'Marked hilarious. Promoted in Best Roasts.':'Rating cleared.',()=>setRating(id,previous===0?next:previous));}catch(e){toast(e.message);}finally{pendingRatings.delete(id);render({updateHash:!selected});if(selected?.id===id)document.querySelectorAll('#detail [data-rate]').forEach(b=>b.setAttribute('aria-pressed',String(ratings[id]===Number(b.dataset.rating))));}}
async function setFavorite(id,favorite){if(!syncReady||pendingFavorites.has(id))return false;pendingFavorites.add(id);try{await apiRequest('/api/favorites',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,favorite})});accountRevision++;saved=favorite?[...new Set([...saved,id])]:saved.filter(x=>x!==id);try{localStorage.setItem('dem-boyz-saved',JSON.stringify(saved));}catch{}render({updateHash:!selected});if(selected?.id===id&&$('#detail-save')){$('#detail-save').textContent=favorite?'♥ Saved':'♡ Save';$('#detail-save').setAttribute('aria-pressed',String(favorite));}return true;}catch(error){toast(error.message||'Could not save your favorite.');return false;}finally{pendingFavorites.delete(id);}}
async function toggleSave(id){if(removedIds.has(id))return;const favorite=!saved.includes(id);if(await setFavorite(id,favorite))toast(favorite?'Favorite saved on this device.':'Removed from favorites.');}
const imageCache=new Map();async function loadImage(src){if(imageCache.has(src))return imageCache.get(src);const promise=new Promise((resolve,reject)=>{const img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('That image could not be loaded.'));img.src=src;});imageCache.set(src,promise);try{return await promise;}catch(e){imageCache.delete(src);throw e;}}
function wrapText(ctx,text,maxWidth){const words=text.toUpperCase().split(/\s+/).filter(Boolean),lines=[];let line='';for(let word of words){if(ctx.measureText(word).width>maxWidth){if(line){lines.push(line);line='';}while(word.length&&ctx.measureText(word).width>maxWidth){let n=word.length;while(n>1&&ctx.measureText(word.slice(0,n)).width>maxWidth)n--;lines.push(word.slice(0,n));word=word.slice(n);}}const trial=line?line+' '+word:word;if(ctx.measureText(trial).width>maxWidth&&line){lines.push(line);line=word;}else line=trial;}if(line)lines.push(line);return lines;}
function paintMeme(canvas,img,{top='',bottom='',size=7,color='#ffffff',layout='classic',shape='original'}={},bounce=0){const max=canvas.dataset.exportSize?Number(canvas.dataset.exportSize):1000;const ratio=shape==='square'?1:shape==='story'?16/9:shape==='wide'?9/16:img.naturalHeight/img.naturalWidth;canvas.width=max;canvas.height=Math.min(2000,Math.max(100,Math.round(max*ratio)));const ctx=canvas.getContext('2d',{willReadFrequently:true});const w=canvas.width,h=canvas.height;ctx.fillStyle='#061426';ctx.fillRect(0,0,w,h);const crop=Math.max(w/img.naturalWidth,h/img.naturalHeight);ctx.drawImage(img,(w-img.naturalWidth*crop)/2,(h-img.naturalHeight*crop)/2,img.naturalWidth*crop,img.naturalHeight*crop);ctx.textAlign='center';ctx.textBaseline='top';const pad=shape==='story'?w*.12:w*.05;
 function drawCaption(text,isBottom){if(!text.trim())return;let fontSize=w*Number(size)/100;ctx.font=`900 ${fontSize}px Impact, "Arial Narrow", sans-serif`;let lines=wrapText(ctx,text,w-pad*2);while(lines.length*fontSize*1.12>h*.39&&fontSize>14){fontSize-=2;ctx.font=`900 ${fontSize}px Impact, "Arial Narrow", sans-serif`;lines=wrapText(ctx,text,w-pad*2);}const lineHeight=fontSize*1.12;let y=isBottom?h-pad-lines.length*lineHeight:pad;y+=bounce;if(layout==='banner'){ctx.fillStyle='#061426df';ctx.fillRect(0,isBottom?y-pad/2:0,w,lines.length*lineHeight+pad*1.5);}ctx.fillStyle=color;ctx.strokeStyle='#000';ctx.lineWidth=fontSize*.095;ctx.lineJoin='round';for(const line of lines){ctx.strokeText(line,w/2,y);ctx.fillText(line,w/2,y);y+=lineHeight;}}
 drawCaption(top,false);drawCaption(bottom,true);return canvas;}
function canvasBlob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Could not export this image.')),'image/png'));}
function paintXPost(canvas,img,m){
 const width=Math.min(1200,img.naturalWidth),pad=Math.round(width*.04),font=Math.max(18,Math.round(width*.038)),lineHeight=font*1.3;
 canvas.width=width;const ctx=canvas.getContext('2d');ctx.font=`600 ${font}px Arial, sans-serif`;const lines=wrapText(ctx,m.caption,width-pad*2),header=Math.ceil(lines.length*lineHeight+pad*2),photoHeight=Math.round(width*img.naturalHeight/img.naturalWidth),footer=Math.max(38,Math.round(width*.065));canvas.height=header+photoHeight+footer;
 ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,canvas.height);ctx.fillStyle='#101d2e';ctx.font=`600 ${font}px Arial, sans-serif`;ctx.textBaseline='top';lines.forEach((line,index)=>ctx.fillText(line,pad,pad+index*lineHeight));ctx.drawImage(img,0,header,width,photoHeight);ctx.font=`${Math.max(12,Math.round(width*.018))}px Arial, sans-serif`;ctx.fillText(`${m.author||'X'} · ${postDate(m)} · X`,pad,header+photoHeight+footer*.3);return canvas;
}
async function mediaBlob(m){if(m.type==='meme'){const img=await loadImage(m.src),canvas=document.createElement('canvas');if(m.top){paintMeme(canvas,img,m);}else if(m.sourcePostDate&&m.caption){paintXPost(canvas,img,m);}else{const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);}return canvasBlob(canvas);}const response=await fetch(m.src);if(!response.ok)throw new Error('The source is unavailable.');return response.blob();}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const fileName=(title,ext)=>'dem-boyz-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,55)+'.'+ext;
async function copyText(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?message:'Copy is unavailable in this browser.');}}
async function openDetail(m,{updateHash=true}={}){if(!syncReady)return;if(removedIds.has(m.id)&&view!=='removed'){setView('removed');toast('This item is in Removed items. Restore it to bring it back.');return;}if(m.type==='template'&&!removedIds.has(m.id)){openMaker(m);return;}selected=m;const dialog=$('#detail');$('#detail-body').innerHTML=`<div class="detail-layout"><div id="detail-preview">${m.type==='video'?`<video class="detail-media" src="${escape(m.src)}" poster="${escape(m.poster||m.preview||'')}" controls playsinline preload="metadata" aria-label="${escape(m.title)}"></video>`:`<img class="detail-media" src="${escape(m.src)}" alt="${escape(m.title)}">`}</div><div class="detail-content"><span class="tag ${isJerry(m)?'jerry-tag':''}">${escape(isJerry(m)?'Jerry’s World':m.category==='Jerry’s World'?'Cowboys':m.category)}</span><h2 id="detail-title">${escape(m.title)}</h2>${m.sourcePostDate?`<p class="post-credit">Posted ${escape(postDate(m))} · ${escape(m.author||'X')}</p>`:''}<p>${escape(m.top?m.top+' / '+m.bottom:['gif','video'].includes(m.type)?(m.caption||'Your saved media.'):m.origin==='community'?(m.caption||'A Cowboys meme from the community archive.'): 'Your saved creation.')}</p>${m.curated?`<p class="quality-label">${escape(qualityLabel(m))}</p>`:''}${ratingButtons(m)}<div class="detail-actions"><button class="button primary" id="detail-download">↓ Download ${m.type==='video'?'MP4':m.type==='gif'?'GIF':'PNG'}</button><button class="button outline" id="detail-share">↗ Share</button><button class="button outline" id="detail-save" ${removedIds.has(m.id)?'hidden':''} aria-pressed="${saved.includes(m.id)}">${saved.includes(m.id)?'♥ Saved':'♡ Save'}</button>${['meme','video','gif'].includes(m.type)&&!removedIds.has(m.id)?`<button class="button outline" id="detail-remix">${['video','gif'].includes(m.type)?'✎ Edit / caption / trim':'✎ Edit meme'}</button>`:''}<button class="button outline" id="detail-collection">＋ Add to collection</button><button class="button ghost" id="detail-copy">Copy caption</button></div><div class="detail-tagging" ${removedIds.has(m.id)?'hidden':''}><button class="button outline" id="detail-jerry" ${!syncReady?'disabled':''} aria-pressed="${isJerry(m)}">${isJerry(m)?'★ In Jerry’s World':'+ Add to Jerry’s World'}</button><p class="saved-note">Tags save in this browser.</p></div><div class="detail-removal-row">${removalButton(m,true)}<p class="saved-note">${removedIds.has(m.id)?'Restore to return this item to your library.':'Remove from your library. You can restore it from Removed items.'}</p></div>${m.sourceUrl?`<a class="source-link" href="${escape(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">${'Source · '+escape(m.sourceName||(m.type==='gif'?'Tenor':'Imgflip'))+(m.author?' / '+escape(m.author):'')} ↗</a>`:`<p class="saved-note">${m.cloud?'Saved in this browser.':'Stored only in this browser.'}</p>`}</div></div>`;if(!dialog.open)dialog.showModal();if(updateHash&&!m.id.startsWith('custom-'))history.replaceState(null,'','#item='+m.id);
 if(m.top){try{const img=await loadImage(m.src);if(selected!==m)return;const canvas=document.createElement('canvas');canvas.className='detail-media';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',m.top+' '+m.bottom);paintMeme(canvas,img,m);$('#detail-preview').replaceChildren(canvas);}catch{toast('Image unavailable. You can still visit the original source.');}}
 if(selected!==m||!dialog.open)return;
 $('#detail-download').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{downloadBlob(await mediaBlob(m),fileName(m.title,m.type==='video'?'mp4':m.type==='gif'?'gif':'png'));toast('Download complete.');}catch{toast('Download unavailable. Open the original source below.');}finally{b.disabled=false;}};
 $('#detail-collection').onclick=()=>{dialog.close();workspace.openMemberships(m);};
 $('#detail-jerry').onclick=()=>toggleJerry(m.id);$('#detail-save').onclick=()=>toggleSave(m.id);$('#detail-copy').onclick=()=>copyText(m.top?m.top+'\n'+m.bottom:(m.caption||m.title),'Caption copied.');$('#detail-remix')?.addEventListener('click',async()=>{dialog.close();if(['video','gif'].includes(m.type)){setView('video');videoStudio.setJerry(isJerry(m));try{const blob=await mediaBlob(m);await videoStudio.loadFile(new File([blob],fileName(m.title,m.type==='gif'?'gif':'mp4'),{type:m.type==='gif'?'image/gif':'video/mp4'}),{title:m.title,caption:m.caption,sourceUrl:m.sourceUrl,author:m.author});}catch{toast('Could not open the saved video. Try again.');}}else openMaker(m);});
 $('#detail-share').onclick=async()=>{if(navigator.share){try{const blob=await mediaBlob(m);const file=new File([blob],fileName(m.title,m.type==='video'?'mp4':m.type==='gif'?'gif':'png'),{type:blob.type});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:m.title});return;}}catch(e){if(e.name==='AbortError')return;}}if(m.type==='video'){toast('Download the MP4 to share this video.');return;}if(m.type==='gif'){if(m.src.startsWith('blob:')||m.src.startsWith('data:')){toast('Download the GIF to share this saved creation.');return;}await copyText(new URL(m.src,location.href).href,'GIF link copied.');return;}if(navigator.clipboard?.write&&typeof ClipboardItem!=='undefined'){try{const png=await mediaBlob(m);await navigator.clipboard.write([new ClipboardItem({'image/png':png})]);toast('Meme image copied.');return;}catch{}}toast('Download the PNG to share this meme.');};}
function showSources(){selected=null;$('#detail-body').innerHTML=`<div class="source-copy"><h2 id="detail-title">Sources and storage</h2><p>A searchable collection of ${number(catalogCounts().memes)} Cowboys memes, ${number(catalogCounts().gifs)} animated reactions, ${number(catalogCounts().videos)} video clips, and ${catalogCounts().templates} editable templates, including a dedicated Jerry Jones collection. The catalog includes ${number(archiveMedia.length)} source-attributed community entries alongside the original meme collection. Entries are deduplicated by source IDs and media URLs; source availability can change. Indexed ${new Date(catalogInfo.indexedAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}. Handpicked roasts are visually reviewed for readable captions and a clear Cowboys or Jerry Jones joke. Other imported entries are screened using public titles, descriptions and tags. Similar edits or clips may appear from different uploads.</p><h3>Images & GIFs</h3><p>Community memes and GIFs link to their source pages and retain creator attribution where available. Imported image captions are part of the original image; remixing adds your text on top. Choose a blank template or upload a photo to start fresh.</p><p>Classic meme templates come from <a href="https://imgflip.com/memetemplates" target="_blank" rel="noopener noreferrer">Imgflip</a>. Jerry Jones still-image templates are sourced from the attributed reaction clips. GIFs are hosted by <a href="https://tenor.com/search/dallas-cowboys-memes-gifs" target="_blank" rel="noopener noreferrer">Tenor</a>, <a href="https://giphy.com/search/dallas-cowboys" target="_blank" rel="noopener noreferrer">GIPHY</a>, and Imgflip. Each item links to its original source and creator where available. Third-party images belong to their respective owners; attribution does not grant a license for other uses.</p><p>The Cowboys star is sourced from the <a href="https://static.www.nfl.com/league/api/clubs/logos/DAL.svg" target="_blank" rel="noopener noreferrer">NFL’s team asset library</a>. Team marks are used to identify this fan-made parody.</p><h3>X / Twitter picks and imports</h3><p>The From X collection contains selected September 2026 posts. Cards show the original posting date and link to the source. New public posts are reviewed weekly; only worthwhile picks are added. Ratings are personal and saved in this browser. Reaction clips can reuse older footage; the date refers to the X post.</p><p>Paste a public post link in Import from X. Videos and animated GIFs are resolved using the <a href="https://docs.fxembed.com/" target="_blank" rel="noopener noreferrer">FxTwitter public API</a>. Imports are limited to 20 MB; private, deleted, or unavailable posts cannot be imported. Save the original MP4 or create a captioned GIF. Saved imports keep a link to their source post.</p><h3>Your creations</h3><p>Original uploads are processed in your browser. Creations you choose to save, Jerry’s World tags, and item removals stay in this browser on this device. There is no account or sign-in. Removed items can be restored from Removed items. Favorites, collections, and editable projects also stay on this device. Clearing site data removes these saves. Download files for a lasting copy or to move them to another device.</p><p>Caption suggestions come from a built-in collection. No AI subscription or API key needed. GIF export uses the open-source <a href="https://github.com/mattdesl/gifenc" target="_blank" rel="noopener noreferrer">gifenc</a> library (MIT license).</p><p>The Jerry’s World hero is an original AI-generated satirical illustration.</p><p>Fan-made parody. Not affiliated with the Dallas Cowboys or the NFL.</p></div>`;$('#detail').showModal();}
const editor={src:templates[0].src,template:templates[0].id,top:'WHEN YOU HIRE YOURSELF AS GM',bottom:'AND STILL BLAME THE COACH',size:7,color:'#ffffff',layout:'classic',shape:'original'};let editorImage,drawVersion=0,uploadUrl;
function initMaker(){maker.innerHTML=`<div class="maker-header"><div><span class="eyebrow"><span class="slash">//</span> MEME CREATOR</span><h1>CREATE A <span>MEME.</span></h1><p>Upload an image or choose a template, add captions, and download.</p></div><button class="back-link" data-view="library">← Back to library</button></div><div class="creator-switch"><button class="active" aria-current="page">Image meme</button><button data-view="video">Video to GIF</button></div><div class="maker-layout"><div><div class="canvas-wrap"><canvas id="meme-canvas" role="img" aria-label="Live preview of your custom meme"></canvas></div><p class="preview-note">LIVE PREVIEW · EDITABLE CAPTIONS</p><p class="remix-note" id="remix-note" hidden>Existing text is part of this image. Add your own captions, or choose a clean template below.</p></div><div class="editor-panel"><div class="editor-section"><span class="control-label">01 / Choose image</span><div class="template-strip">${visibleTemplates().map(t=>`<button class="template-thumb" data-template="${t.id}" aria-label="Use ${escape(t.name)}" title="${escape(t.name)}"><img src="${t.src}" alt="${escape(t.name)}" loading="lazy"></button>`).join('')}</div><button class="button outline upload-button" id="upload-button">↑ Upload your own photo</button><p class="saved-note" id="upload-name">JPG, PNG or WebP · up to 15 MB</p></div><div class="editor-section"><div class="creator-small-title"><span class="control-label">02 / Add captions</span><button class="suggest" id="suggest-caption">↻ Suggest caption</button></div><label class="field"><span>Top text <span class="char-count" id="top-count"></span></span><textarea id="top-text" maxlength="120" placeholder="Enter top caption"></textarea></label><label class="field"><span>Bottom text <span class="char-count" id="bottom-count"></span></span><textarea id="bottom-text" maxlength="120" placeholder="Enter bottom caption"></textarea></label><div class="editor-row"><label><span class="control-label">Text style</span><select id="text-layout"><option value="classic">Classic outline</option><option value="banner">Dark banner</option></select></label><label><span class="control-label">Share preset</span><select id="image-shape"><option value="original">Original</option><option value="square">Group chat · square</option><option value="story">Story · 9:16</option><option value="wide">X post · 16:9</option></select></label><label><span class="control-label">Color</span><input type="color" id="text-color" value="#ffffff" aria-label="Caption color"></label></div><label class="field" style="margin-top:18px;margin-bottom:0"><span>Text size</span><div class="editor-row"><span>A</span><input type="range" min="4" max="11" step="0.5" id="text-size" value="7" aria-label="Caption font size"><strong>A</strong></div></label></div><div class="editor-section"><span class="control-label">03 / Download</span><div class="export-actions"><button class="button primary" id="export-png">↓ Download PNG</button><button class="button outline" id="export-gif">▷ Download GIF</button></div><p class="saved-note">GIF adds a subtle caption bounce. PNG keeps the crispest image.</p><label class="check-label"><input type="checkbox" id="maker-jerry-tag"> Add to Jerry’s World</label><p class="saved-note">Saved creations stay in this browser.</p><button class="button outline upload-button" id="save-creation">♡ Save to my collection</button><label class="field project-title"><span>Project name</span><input id="image-project-title" maxlength="100" placeholder="My Jerry meme"></label><button class="button outline upload-button" id="save-image-project">Save editable project</button><p class="saved-note">Saves the source image and your editable captions in this browser.</p></div></div></div><p class="maker-bottom">Save to my collection stores the finished meme. Save editable project also stores your source image and settings.</p>`;
 mountCaptionPacks($('.editor-panel .editor-section:nth-child(2)'),c=>{editor.top=c.top;editor.bottom=c.bottom;$('#maker-jerry-tag').checked=true;syncEditor();drawEditor();});$('#save-image-project').onclick=saveImageProject;
 $('#top-text').addEventListener('input',e=>{editor.top=e.target.value;drawEditor();});$('#bottom-text').addEventListener('input',e=>{editor.bottom=e.target.value;drawEditor();});$('#text-size').addEventListener('input',e=>{editor.size=Number(e.target.value);drawEditor();});$('#text-color').addEventListener('input',e=>{editor.color=e.target.value;drawEditor();});$('#text-layout').addEventListener('change',e=>{editor.layout=e.target.value;drawEditor();});$('#image-shape').addEventListener('change',e=>{editor.shape=e.target.value;drawEditor();});
 $('#upload-button').onclick=()=>$('#file-upload').click();$('#suggest-caption').onclick=()=>{const isJerryTemplate=templates.find(t=>t.id===editor.template)?.subject==='Jerry Jones';const options=media.filter(m=>!removedIds.has(m.id)&&m.type==='meme'&&m.top&&(!isJerryTemplate||isJerry(m)));let m=options[Math.floor(Math.random()*options.length)];if(!m){toast('No caption suggestions available. Add your own text.');return;}editor.top=m.top;editor.bottom=m.bottom;syncEditor();drawEditor();toast('Caption added.');};$('#export-png').onclick=()=>exportMeme('png');$('#export-gif').onclick=()=>exportMeme('gif');$('#save-creation').onclick=saveCreation;syncEditor();}
function refreshTemplates(){if(!maker.innerHTML)return;const available=visibleTemplates();$('.template-strip').innerHTML=available.map(t=>`<button class="template-thumb" data-template="${t.id}" aria-label="Use ${escape(t.name)}" title="${escape(t.name)}"><img src="${t.src}" alt="${escape(t.name)}" loading="lazy"></button>`).join('');if(editor.template&&removedIds.has('t'+editor.template)){const next=available[0];editor.src=next?.src||'';editor.template=next?.id||'';editorImage=null;drawEditor();}syncEditor();}
function syncEditor(){if(!$('#top-text'))return;for(const id of ['export-png','export-gif','save-creation'])$('#'+id).disabled=!editor.src;$('#top-text').value=editor.top;$('#bottom-text').value=editor.bottom;$('#text-size').value=editor.size;$('#text-color').value=editor.color;$('#text-layout').value=editor.layout;$('#image-shape').value=editor.shape;document.querySelectorAll('[data-template]').forEach(b=>{b.classList.toggle('active',b.dataset.template===editor.template);b.setAttribute('aria-pressed',b.dataset.template===editor.template);});}
async function drawEditor(){if(!$('#meme-canvas'))return;const current=++drawVersion;if(!editor.src){const canvas=$('#meme-canvas');canvas.width=800;canvas.height=500;const ctx=canvas.getContext('2d');ctx.fillStyle='#0b2039';ctx.fillRect(0,0,800,500);ctx.fillStyle='#c9d8eb';ctx.textAlign='center';ctx.font='24px sans-serif';ctx.fillText('Upload a photo to start your meme',400,250);return;}$('#top-count').textContent=editor.top.length+'/120';$('#bottom-count').textContent=editor.bottom.length+'/120';try{const img=await loadImage(editor.src);if(current!==drawVersion)return;editorImage=img;paintMeme($('#meme-canvas'),img,editor);}catch{toast('That image could not be loaded. Choose another template.');}}
function openMaker(m){imageSourceVersion++;imageProjectId=null;if(m){editor.src=m.src;editor.template=m.template||'';editor.top=m.top||'';editor.bottom=m.bottom||'';editor.layout=m.layout||'classic';}setView('maker');$('#remix-note').hidden=m?.origin!=='community';$('#maker-jerry-tag').checked=!!m&&isJerry(m);syncEditor();drawEditor();}
$('#file-upload').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG, or WebP photo.');e.target.value='';return;}if(file.size>15*1024*1024){toast('Choose an image smaller than 15 MB.');e.target.value='';return;}const url=URL.createObjectURL(file);try{const img=await loadImage(url);if(img.naturalWidth*img.naturalHeight>40000000)throw new Error('too large');if(uploadUrl){imageCache.delete(uploadUrl);URL.revokeObjectURL(uploadUrl);}uploadUrl=url;imageSourceVersion++;imageProjectId=null;editor.src=url;editor.template='';$('#remix-note').hidden=true;$('#upload-name').textContent=file.name;syncEditor();await drawEditor();toast('Photo loaded.');}catch{imageCache.delete(url);URL.revokeObjectURL(url);toast('Could not open that photo. Try a smaller image.');}e.target.value='';});
async function exportMeme(format){const button=$(format==='gif'?'#export-gif':'#export-png'),original=button.textContent;button.disabled=true;const snapshot={...editor};try{const img=await loadImage(snapshot.src);const canvas=document.createElement('canvas');if(format==='png'){paintMeme(canvas,img,snapshot);downloadBlob(await canvasBlob(canvas),'dem-boyz-my-meme.png');}else{button.textContent='Making GIF…';const {GIFEncoder,quantize,applyPalette}=await import('./assets/gifenc.js');canvas.dataset.exportSize='560';const gif=GIFEncoder();let palette;for(let frame=0;frame<8;frame++){paintMeme(canvas,img,snapshot,Math.sin(frame/8*Math.PI*2)*7);const {width:w,height:h}=canvas,rgba=canvas.getContext('2d').getImageData(0,0,w,h).data;if(!palette){palette=quantize(rgba,253);palette.push([0,0,0],[255,255,255],snapshot.color.slice(1).match(/.{2}/g).map(v=>parseInt(v,16)));}gif.writeFrame(applyPalette(rgba,palette),w,h,{...(frame===0?{palette}:{}),delay:110,repeat:0});button.textContent=`Making GIF… ${Math.round((frame+1)/8*100)}%`;await new Promise(resolve=>setTimeout(resolve,0));}gif.finish();downloadBlob(new Blob([gif.bytes()],{type:'image/gif'}),'dem-boyz-my-meme.gif');}toast('Download complete.');}catch(error){console.error(error);toast('Export failed. Try a smaller photo or choose PNG.');}finally{button.disabled=false;button.textContent=original;}}
async function saveCreation(){const button=$('#save-creation');button.disabled=true;try{const snapshot={...editor},img=await loadImage(snapshot.src),canvas=document.createElement('canvas');canvas.dataset.exportSize='700';paintMeme(canvas,img,snapshot);await saveCloudCreation({blob:await canvasBlob(canvas),poster:canvas.toDataURL('image/jpeg',.85),title:(snapshot.bottom||snapshot.top||'My Cowboys meme').slice(0,100),caption:[snapshot.top,snapshot.bottom].filter(Boolean).join(' / '),width:canvas.width,height:canvas.height,jerry:$('#maker-jerry-tag').checked});toast('Meme saved to your account.');}catch(error){toast(error.message||'Could not save. Download your meme to keep a copy.');}finally{button.disabled=false;}}
async function apiRequest(path,options={}){return localApi(path,options);}
async function syncAccount(){const banner=$('#library-sync-status'),revision=accountRevision;try{if(!readStore('dem-boyz-favorites-migrated',false)&&saved.length){await apiRequest('/api/favorites/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:saved})});try{localStorage.setItem('dem-boyz-favorites-migrated','true');}catch{}}const [data,ws]=await Promise.all([apiRequest('/api/library'),apiRequest('/api/workspace')]);if(revision===accountRevision){jerryTags=data.tags||{};cloudCreations=data.creations||[];removedIds=new Set(data.removed||[]);ratings=ws.ratings||{};saved=ws.favorites;folders=ws.collections;memberships=ws.memberships;projects=ws.projects;}syncReady=true;banner.hidden=true;refreshTemplates();if(location.hash.startsWith('#item='))routeHash();else {render({updateHash:!selected});if(['collections','projects'].includes(view))workspace.render(view);}if(selected&&$('#detail-jerry'))$('#detail-jerry').disabled=false;return true;}catch(error){banner.hidden=false;banner.querySelector('span').textContent=error.message;syncReady=true;banner.querySelector('span').textContent=error.message+' You can still browse, create, and download. Use Retry to reopen storage.';render({updateHash:!selected});return false;}}
async function saveCloudCreation({id='custom-'+crypto.randomUUID(),blob,poster,title,caption='',width,height,jerry=false,sourceUrl='',author=''}){if(pendingCreationSaves.has(id)||pendingRemovals.has(id))throw new Error('This creation is already being saved.');pendingCreationSaves.add(id);render({updateHash:!selected});try{if(!syncReady&&!await syncAccount())throw new Error('Saved items are unavailable. Download your creation and try saving again later.');const form=new FormData();form.set('id',id);form.set('file',blob,blob.type==='video/mp4'?'creation.mp4':blob.type==='image/gif'?'creation.gif':'creation.png');if(poster)form.set('poster',await(await fetch(poster)).blob(),'poster.jpg');for(const [key,value]of Object.entries({title:title.slice(0,100),caption:caption.slice(0,500),width,height,jerry,sourceUrl,author}))form.set(key,String(value));const data=await apiRequest('/api/creations',{method:'POST',body:form});accountRevision++;removedIds.delete(id);cloudCreations=[data.item,...cloudCreations.filter(m=>m.id!==id)];jerryTags[id]=data.tagged;render({updateHash:!selected});return data.item;}finally{pendingCreationSaves.delete(id);render({updateHash:!selected});}}
async function toggleJerry(id){if(!syncReady){toast('Load saved tags before changing this collection.');return;}const m=findMedia(id);if(!m||removedIds.has(id)||pendingTags.has(id)||pendingRemovals.has(id)||pendingCreationSaves.has(id))return;pendingTags.add(id);const tagged=!isJerry(m);render();const detailButton=$('#detail-jerry');if(detailButton)detailButton.disabled=true;try{if(m.id.startsWith('custom-')&&!m.cloud){const image=await loadImage(m.src);const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);await saveCloudCreation({id:m.id,blob:await mediaBlob(m),poster:canvas.toDataURL('image/jpeg',.8),title:m.title,width:canvas.width,height:canvas.height,jerry:tagged});}else{await apiRequest('/api/tags',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,tagged})});accountRevision++;jerryTags[id]=tagged;}toast(tagged?'Added to Jerry’s World.':'Removed from Jerry’s World.');}catch(error){toast(error.message);}finally{pendingTags.delete(id);render();if(selected?.id===id&&$('#detail-jerry')){$('#detail-jerry').disabled=false;$('#detail-jerry').textContent=isJerry(m)?'★ In Jerry’s World':'+ Add to Jerry’s World';$('#detail-jerry').setAttribute('aria-pressed',isJerry(m));}}}
$('#retry-sync').onclick=syncAccount;
const cleanup=createCleanup({items:allMedia,removed:()=>removedIds,remove:setRemoved,open:id=>{const m=findMedia(id);if(m)openDetail(m);},toast});$('#cleanup-library').onclick=()=>cleanup.show();
$('#collection-filter').onchange=e=>{collectionId=e.target.value;page=1;render();};$('#review-library').onclick=()=>workspace.openReview(itemsForView());

let searchTimer;$('#search').addEventListener('input',e=>{query=e.target.value;page=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>render(),140);});$('#sort').addEventListener('change',e=>{sort=e.target.value;page=1;render();});$('#source-filter').addEventListener('change',e=>{sourceFilter=e.target.value;page=1;render();});$('#topic-clear').onclick=()=>{topic='';page=1;render();};$('#prev-page').onclick=()=>changePage(page-1);$('#next-page').onclick=()=>changePage(page+1);$('#page-jump-form').onsubmit=e=>{e.preventDefault();changePage(Number($('#page-jump').value));};$('#random-top').onclick=()=>{const choices=itemsForView().filter(m=>!removedIds.has(m.id)&&m.type!=='template');if(!choices.length){toast('Clear your filters to find more memes.');return;}openDetail(choices[Math.floor(Math.random()*choices.length)]);};$('#about').onclick=showSources;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.newProject){if(b.dataset.newProject==='image'){openMaker({src:visibleTemplates()[0]?.src||'',top:'',bottom:'',layout:'classic'});$('#image-project-title').value='';}else{setView('video');videoStudio.reset();}}if(b.dataset.view)setView(b.dataset.view);if(b.dataset.feed){feed=b.dataset.feed;page=1;render();}if(b.dataset.reaction!==undefined){const nextReaction=reaction===b.dataset.reaction?'':b.dataset.reaction;setView('library');reaction=nextReaction;feed='archive';page=1;render();}if(b.dataset.rate){setRating(b.dataset.rate,Number(b.dataset.rating));return;}if(b.dataset.collectionItem){const item=findMedia(b.dataset.collectionItem);if(item)workspace.openMemberships(item);}if(b.dataset.source){setView('library');sourceFilter=b.dataset.source;render();$('#section-title').scrollIntoView({behavior:'smooth',block:'start'});}if(b.hasAttribute('data-import-x')){setView('video');videoStudio.focusImport();}if(b.dataset.remove){setRemoved(b.dataset.remove,!removedIds.has(b.dataset.remove));return;}if(b.hasAttribute('data-jerry-maker')){const t=visibleTemplates().find(t=>t.subject==='Jerry Jones');if(!t){setView('maker');toast('Upload a photo or restore a Jerry template to start.');return;}openMaker({...t,template:t.id,top:'WHEN YOU HIRE YOURSELF AS GM',bottom:'EMPLOYEE OF THE MONTH. AGAIN.'});$('#maker-jerry-tag').checked=true;}if(b.dataset.jerryTag)toggleJerry(b.dataset.jerryTag);if(b.dataset.filter){filter=b.dataset.filter;page=1;if(filter==='template')sourceFilter='all';if(view==='gifs'&&filter!=='gif')view='library';render();}if(b.dataset.topic){setView('library');topic=b.dataset.topic;render();$('#section-title').scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.page)changePage(Number(b.dataset.page));if(b.hasAttribute('data-reset'))setView('library');if(b.dataset.open){const m=findMedia(b.dataset.open);if(m)openDetail(m);}if(b.dataset.save)toggleSave(b.dataset.save);if(b.dataset.template){const t=visibleTemplates().find(t=>t.id===b.dataset.template);if(t){imageSourceVersion++;editor.src=t.src;editor.template=t.id;$('#remix-note').hidden=true;$('#upload-name').textContent='JPG, PNG or WebP · up to 15 MB';syncEditor();drawEditor();}}if(b.classList.contains('dialog-close')&&b.closest('#detail'))$('#detail').close();});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#detail').addEventListener('close',()=>{$('#detail video')?.pause();selected=null;syncLibraryHash();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail').open&&!['maker','video','collections','projects'].includes(view)){e.preventDefault();$('#search').focus();}});
function syncLibraryHash(){if(selected)return;if(['maker','video','collections','projects'].includes(view)){history.replaceState(null,'','#'+view);return;}const params=new URLSearchParams();if(query)params.set('q',query);if(filter!=='all')params.set('type',filter);if(topic)params.set('topic',topic);if(feed==='archive')params.set('feed',feed);if(reaction)params.set('reaction',reaction);if(collectionId)params.set('collection',collectionId);if(sourceFilter!=='all')params.set('source',sourceFilter);if(sort!=='featured')params.set('sort',sort);if(page>1)params.set('page',page);history.replaceState(null,'','#'+view+(params.size?'?'+params:''));}
function renderPagination(total,pages,start){$('#pagination-summary').textContent=total?`Showing ${number(start+1)}–${number(Math.min(start+PAGE_SIZE,total))} of ${number(total)} · ${PAGE_SIZE} per page`:'0 results';$('#prev-page').disabled=page<=1;$('#next-page').disabled=page>=pages;$('#page-jump').max=pages;$('#page-jump').value=page;const nums=[...new Set([1,page-1,page,page+1,pages])].filter(n=>n>=1&&n<=pages).sort((a,b)=>a-b);let last=0;$('#page-numbers').innerHTML=nums.map(n=>{const gap=last&&n-last>1?'<span aria-hidden="true">…</span>':'';last=n;return gap+`<button data-page="${n}" class="page-number ${n===page?'active':''}" aria-label="Page ${n}" ${n===page?'aria-current="page"':''}>${n}</button>`;}).join('');}
function changePage(next){const pages=Math.max(1,Math.ceil(itemsForView().length/PAGE_SIZE));page=Math.max(1,Math.min(Number.isFinite(next)?Math.trunc(next):1,pages));render();$('#section-title').scrollIntoView({behavior:'instant',block:'start'});}
function routeHash(){const hash=location.hash.slice(1);if(hash.startsWith('item=')){if(!syncReady){setView('library',{updateHash:false});return;}let id;try{id=decodeURIComponent(hash.slice(5));}catch{id='';}const m=findMedia(id);if(m){setView('library',{updateHash:false});openDetail(m,{updateHash:false});return;}}const [route,rawParams]=hash.split('?');setView(['library','jerry','gifs','maker','video','saved','removed','collections','projects'].includes(route)?route:'library',{updateHash:false});if(!['maker','video','collections','projects'].includes(view)){const params=new URLSearchParams(rawParams);query=(params.get('q')||'').slice(0,200);const type=params.get('type');if(['all','meme','gif','video','template'].includes(type))filter=type;topic=params.get('topic')||'';feed=params.get('feed')==='archive'?'archive':'best';reaction=reactions.some(r=>r[0]===params.get('reaction'))?params.get('reaction'):'';collectionId=params.get('collection')||'';sourceFilter=['x','picks','community','original'].includes(params.get('source'))?params.get('source'):'all';sort=['newest','posted','az'].includes(params.get('sort'))?params.get('sort'):'featured';page=Math.max(1,Math.trunc(Number(params.get('page')))||1);render();}}
window.addEventListener('hashchange',routeHash);routeHash();syncAccount();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'search_meme_library',title:'Search Cowboys memes',description:'Filter the visible meme library by text and media type. Returns matching items; does not download or share.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200},type:{type:'string',enum:['all','meme','gif','video','template']}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||input.type&&!['all','meme','gif','video','template'].includes(input.type))throw new Error('Invalid search input.');setView('library');query=input.query;filter=input.type||'all';render();return{count:itemsForView().length,items:itemsForView().slice(0,20).map(({id,title,type})=>({id,title,type}))};}},{name:'stage_custom_meme',title:'Prepare a custom meme',description:'Open the meme editor and set a template and captions for review. Does not save, export, or share.',inputSchema:{type:'object',properties:{templateId:{type:'string'},top:{type:'string',maxLength:120},bottom:{type:'string',maxLength:120}},required:['templateId','top','bottom'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){const t=visibleTemplates().find(t=>t.id===input?.templateId);if(!t||typeof input.top!=='string'||typeof input.bottom!=='string'||input.top.length>120||input.bottom.length>120)throw new Error('Invalid template or caption.');openMaker({...t,template:t.id,top:input.top,bottom:input.bottom});await drawEditor();return{status:'staged',templateId:t.id,top:editor.top,bottom:editor.bottom};}}];for(const tool of registrations){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

async function refreshWorkspace(){for(let attempt=0;attempt<3;attempt++){const revision=accountRevision,data=await apiRequest('/api/workspace');if(revision!==accountRevision)continue;ratings=data.ratings||{};saved=data.favorites;folders=data.collections;memberships=data.memberships;projects=data.projects;accountRevision++;if(!['maker','video','collections','projects'].includes(view))render({updateHash:!selected});return data;}return null;}
async function saveProject({id='project-'+crypto.randomUUID(),title,kind,settings,source,poster}){const form=new FormData();for(const [name,value] of Object.entries({id,title,kind,settings:JSON.stringify(settings)}))form.set(name,value);if(source)form.set('source',source,source.name||'source.png');if(poster)form.set('poster',await(await fetch(poster)).blob(),'poster.jpg');const data=await apiRequest('/api/projects',{method:'POST',body:form});accountRevision++;projects=[data.project,...projects.filter(p=>p.id!==data.project.id)];if(view==='projects')workspace.render('projects');toast('Editable project saved.');return data.project;}
async function saveImageProject(){const b=$('#save-image-project'),snapshot={...editor},version=imageSourceVersion,id=imageProjectId,title=($('#image-project-title').value.trim()||editor.top||'My image project').slice(0,100),jerry=$('#maker-jerry-tag').checked;b.disabled=true;try{const img=await loadImage(snapshot.src),original=document.createElement('canvas');original.width=img.naturalWidth;original.height=img.naturalHeight;original.getContext('2d').drawImage(img,0,0);const source=new File([await canvasBlob(original)],'original-image.png',{type:'image/png'}),preview=document.createElement('canvas');preview.dataset.exportSize='640';paintMeme(preview,img,snapshot);const project=await saveProject({id:id||undefined,title,kind:'image',settings:{version:1,top:snapshot.top,bottom:snapshot.bottom,size:Number(snapshot.size),color:snapshot.color,layout:snapshot.layout,shape:snapshot.shape,jerry},source:id&&imageSavedSource===snapshot.src?undefined:source,poster:preview.toDataURL('image/jpeg',.85)});if(version===imageSourceVersion){imageProjectId=project.id;imageSavedSource=snapshot.src;}}catch(e){toast(e.message||'Project could not be saved.');}finally{b.disabled=false;}}
async function openProject(id){const generation=++projectOpenGeneration,p=await apiRequest('/api/projects/'+id);if(generation!==projectOpenGeneration)return;const response=await fetch(p.sourceSrc);if(generation!==projectOpenGeneration)return;if(!response.ok)throw new Error('Project source is unavailable.');const file=new File([await response.blob()],p.sourceName,{type:p.sourceMime});if(generation!==projectOpenGeneration)return;if(p.kind==='video'){setView('video');await videoStudio.loadProject(file,p);}else{if(uploadUrl){imageCache.delete(uploadUrl);URL.revokeObjectURL(uploadUrl);}uploadUrl=URL.createObjectURL(file);openMaker({...p.settings,src:uploadUrl});Object.assign(editor,p.settings,{src:uploadUrl,template:''});imageProjectId=id;imageSavedSource=uploadUrl;$('#image-project-title').value=p.title;$('#maker-jerry-tag').checked=p.settings.jerry;syncEditor();await drawEditor();}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&syncReady&&!pendingTags.size&&!pendingRemovals.size&&!pendingFavorites.size&&!pendingRatings.size&&!pendingCreationSaves.size)syncAccount();});
